#!/usr/bin/env python3
"""Create audiobook from Paul Graham essays."""

import os
import re
import subprocess
import requests
import sys
from concurrent.futures import ThreadPoolExecutor

# --- Helper Functions ---

def fetch_article_content(url):
    """Fetch article content using curl for reliability."""
    print(f"Fetching: {url}")
    # Use curl to get raw HTML - more reliable than web fetch tools
    try:
        result = subprocess.run(
            ["curl", "-s", "-L", url], # Added -L to follow redirects
            capture_output=True,
            text=True,
            check=True
        )
        html = result.stdout
    except subprocess.CalledProcessError as e:
        print(f"Error fetching {url}: {e}")
        return ""

    # Specific extraction for Paul Graham's site (often in <font> or <td> tags)
    # But generic stripping often works if we remove script/style first.

    text = re.sub(r'<script[^>]*>.*?</script>', '', html, flags=re.DOTALL | re.IGNORECASE)
    text = re.sub(r'<style[^>]*>.*?</style>', '', text, flags=re.DOTALL | re.IGNORECASE)

    # Try to target the main content if possible. PG site usually puts content in a table.
    # A simple tag stripper is usually robust enough for TTS if we clean up newlines.
    text = re.sub(r'<[^>]+>', ' ', text)

    # Decode HTML entities
    import html as html_lib
    text = html_lib.unescape(text)

    text = re.sub(r'\s+', ' ', text).strip()
    return text

def verify_content(text, expected_min_chars=1000):
    """Basic verification that content is complete."""
    if len(text) < expected_min_chars:
        print(f"WARNING: Content may be truncated ({len(text)} chars)")
        return False
    return True

def clean_text_for_tts(text):
    """Clean text for better TTS output."""
    # Remove URLs
    text = re.sub(r'http[s]?://\S+', '', text)
    # Remove footnote markers like [1], [2]
    text = re.sub(r'\[\d+\]', '', text)
    # Normalize whitespace
    text = re.sub(r'\s+', ' ', text)
    return text.strip()

def chunk_text(text, max_chars=4000):
    """Split text into chunks at sentence boundaries."""
    # Split by sentence endings followed by space
    sentences = re.split(r'(?<=[.!?])\s+', text)
    chunks = []
    current_chunk = ""

    for sentence in sentences:
        if len(current_chunk) + len(sentence) < max_chars:
            current_chunk += sentence + " "
        else:
            if current_chunk:
                chunks.append(current_chunk.strip())
            current_chunk = sentence + " "

    if current_chunk:
        chunks.append(current_chunk.strip())

    return chunks

def concatenate_audio(audio_files, output_path):
    """Concatenate multiple audio files using ffmpeg."""
    if not audio_files:
        return False

    # Create file list for ffmpeg
    list_file = "/tmp/audio_list.txt"
    with open(list_file, "w") as f:
        for audio_file in audio_files:
            # ffmpeg requires absolute paths or relative to list file. 
            # escaping single quotes is important for filenames
            safe_path = audio_file.replace("'", "'\\''")
            f.write(f"file '{safe_path}'\n")

    # Concatenate with ffmpeg
    print(f"Concatenating {len(audio_files)} chunks to {output_path}...")
    result = subprocess.run([
        "ffmpeg", "-y", "-f", "concat", "-safe", "0",
        "-i", list_file, "-c", "copy", output_path
    ], capture_output=True)

    if result.returncode != 0:
        print(f"FFmpeg error: {result.stderr.decode()}")
        return False

    # Cleanup temp files
    for f in audio_files:
        try:
            os.unlink(f)
        except OSError:
            pass
    try:
        os.unlink(list_file)
    except OSError:
        pass

    return True

# --- TTS Providers ---

def create_with_elevenlabs(text, output_path):
    """Generate audiobook using ElevenLabs API."""
    api_key = os.environ.get("ELEVENLABS_API_KEY")
    voice_id = "21m00Tcm4TlvDq8ikWAM"  # Rachel

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    print(f"Processing {len(chunks)} chunks with ElevenLabs...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"  Generating chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                f"https://api.elevenlabs.io/v1/text-to-speech/{voice_id}",
                headers={
                    "xi-api-key": api_key,
                    "Content-Type": "application/json"
                },
                json={
                    "text": chunk,
                    "model_id": "eleven_turbo_v2_5",
                    "voice_settings": {"stability": 0.5, "similarity_boost": 0.75}
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception calling ElevenLabs: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_openai(text, output_path):
    """Generate audiobook using OpenAI TTS API."""
    api_key = os.environ.get("OPENAI_API_KEY")

    chunks = chunk_text(text, max_chars=4000)
    audio_files = []

    print(f"Processing {len(chunks)} chunks with OpenAI...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"  Generating chunk {i+1}/{len(chunks)}...")

        try:
            response = requests.post(
                "https://api.openai.com/v1/audio/speech",
                headers={
                    "Authorization": f"Bearer {api_key}",
                    "Content-Type": "application/json"
                },
                json={
                    "model": "tts-1",
                    "input": chunk,
                    "voice": "onyx",
                    "response_format": "mp3"
                }
            )

            if response.status_code == 200:
                with open(chunk_file, "wb") as f:
                    f.write(response.content)
                audio_files.append(chunk_file)
            else:
                print(f"Error: {response.status_code} - {response.text}")
                return False
        except Exception as e:
            print(f"Exception calling OpenAI: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_with_gtts(text, output_path):
    """Generate audiobook using gTTS (free, no API key)."""
    try:
        from gtts import gTTS
    except ImportError:
        print("Installing gTTS...")
        subprocess.check_call([sys.executable, "-m", "pip", "install", "gTTS"])
        from gtts import gTTS

    chunks = chunk_text(text, max_chars=4500)
    audio_files = []

    print(f"Processing {len(chunks)} chunks with gTTS...")

    for i, chunk in enumerate(chunks):
        chunk_file = f"/tmp/chunk_{i:03d}.mp3"
        print(f"  Generating chunk {i+1}/{len(chunks)}...")

        try:
            tts = gTTS(text=chunk, lang='en', slow=False)
            tts.save(chunk_file)
            audio_files.append(chunk_file)
        except Exception as e:
            print(f"Error with gTTS: {e}")
            return False

    return concatenate_audio(audio_files, output_path)

def create_audiobook(text, output_path):
    """Convert text to audiobook with automatic TTS provider selection."""
    has_elevenlabs = bool(os.environ.get("ELEVENLABS_API_KEY"))
    has_openai = bool(os.environ.get("OPENAI_API_KEY"))

    if has_elevenlabs:
        print("Using ElevenLabs TTS (highest quality)")
        return create_with_elevenlabs(text, output_path)
    elif has_openai:
        print("Using OpenAI TTS (high quality)")
        return create_with_openai(text, output_path)
    else:
        print("Using gTTS (free, no API key required)")
        return create_with_gtts(text, output_path)

# --- Main ---

def main():
    urls = [
        "http://paulgraham.com/ds.html",
        "https://paulgraham.com/foundermode.html"
    ]

    all_text = ""
    for url in urls:
        text = fetch_article_content(url)

        # Simple heuristic to remove header/footer noise often found on simple HTML sites
        # Paul Graham's essays usually end with a specific footer or "Notes" section
        if "Notes" in text[-2000:]:
             text = text.split("Notes")[0] 

        # Specific cleanup for PG sites which often have "Paul Graham" at the top
        # We can add a title announcement

        if "ds.html" in url:
            title = "Do Things that Don't Scale"
        elif "foundermode.html" in url:
            title = "Founder Mode"
        else:
            title = "Essay"

        all_text += f"\n\nTitle: {title}.\n\n{text}\n\nEnd of {title}.\n\n"

    clean_text = clean_text_for_tts(all_text)
    print(f"Total text to convert: {len(clean_text)} characters")

    # Ensure output directory exists
    output_path = "/root/audiobook.mp3"

    success = create_audiobook(clean_text, output_path)

    if success:
        print(f"Audiobook created successfully at {output_path}!")
    else:
        print("Failed to create audiobook")
        sys.exit(1)

if __name__ == "__main__":
    main()

